    roomId = route.room_id;
    deviceId = p.device_id;
    v = p.values?.temperature;
    actual = p.actuators?.fan;
}
if (!userId || !roomId || !deviceId || typeof v !== 'number' || v <= 35) return null;
const key = `${userId}/${roomId}/${deviceId}`;
if (typeof actual !== 'boolean') actual = flow.get(`fanState:${key}`);
let pending = flow.get(`fanAutoPending:${key}`);
if (typeof actual === 'boolean' && pending === actual) {
    pending = null;
    flow.set(`fanAutoPending:${key}`, null);
    flow.set(`fanAutoState:${key}`, actual ? 'on' : 'off');
}
const knownOn = typeof actual === 'boolean' ? actual : flow.get(`fanAutoState:${key}`) === 'on';
